def configure_tesseract():
    """Find the Tesseract executable even when Homebrew is not on the server PATH."""
    if pytesseract is None:
        return None
    candidates = []
    override = os.environ.get("TESSERACT_CMD", "").strip()
    if override:
        candidates.append(override)
    discovered = shutil.which("tesseract")
    if discovered:
        candidates.append(discovered)
    candidates.extend([
        "/opt/homebrew/bin/tesseract",  # Apple Silicon Homebrew
        "/usr/local/bin/tesseract",    # Intel Mac / custom Homebrew
        "/usr/bin/tesseract",          # common Linux install
        "/opt/local/bin/tesseract",    # MacPorts
        r"C:\Program Files\Tesseract-OCR\tesseract.exe",
    ])
    for candidate in candidates:
        if candidate and os.path.isfile(candidate) and os.access(candidate, os.X_OK):
            pytesseract.pytesseract.tesseract_cmd = candidate
            return candidate
    return None


def ocr_status():
    """Return actionable diagnostics for the exact Python process running Flask."""
    if Image is None:
        return {"ready": False, "message": f"Pillow is missing from the Python interpreter running SmartCart ({sys.executable}). Install it with: \"{sys.executable}\" -m pip install Pillow", "python": sys.executable}
    if pytesseract is None:
        return {"ready": False, "message": f"The pytesseract Python package is missing from SmartCart’s active interpreter ({sys.executable}). Install it with: \"{sys.executable}\" -m pip install pytesseract", "python": sys.executable}
    executable = configure_tesseract()
    if not executable:
        return {"ready": False, "message": "The Tesseract executable was not found by the Python process running SmartCart. Set TESSERACT_CMD to its full path, or install it on this machine and restart the app.", "python": sys.executable, "tesseract_path": None}
    try:
        version = str(pytesseract.get_tesseract_version()).splitlines()[0].strip()
        return {"ready": True, "message": "Text recognition ready", "python": sys.executable, "tesseract_path": executable, "version": version}
    except Exception as exc:
        return {"ready": False, "message": "Tesseract was found but could not start. Check the executable and permissions.", "python": sys.executable, "tesseract_path": executable, "detail": str(exc)}
