@app.route("/api/cart/<int:iid>/<action>", methods=["POST"])
def api_cart(iid, action):
    with LOCK:
        it = ITEMS.get(iid)
        if it:
            if action == "inc": it["qty"] = min(9, it["qty"] + 1)
            elif action == "dec": it["qty"] = max(1, it["qty"] - 1)
            elif action == "delete": ITEMS.pop(iid)
        sync_list_from_cart()
    return jsonify(state())


@app.route("/api/cart/recognized", methods=["POST"])
def api_cart_recognized():
    """Register only a confirmed label from the project's trained product catalogue."""
    data = request.get_json(force=True) or {}
    raw_name = re.sub(r"\s+", " ", str(data.get("name", ""))).strip()[:80]
    key = canonical_product(raw_name)
    if not key:
        supported = ", ".join(product["name"] for product in PRODUCT_CATALOG.values())
        return jsonify(error="This product label is not in the trained SmartCart catalogue. Nothing was added.", supported_products=supported.split(", ")), 422
    product = PRODUCT_CATALOG[key]
    try:
        # The catalogue supplies the authoritative name/price/weight; model output cannot invent products.
        confidence = float(data.get("confidence", 1.0))
        if confidence < float(os.environ.get("SMARTCART_MIN_CONFIDENCE", "0.55")):
            return jsonify(error="Recognition confidence is too low. Show the product clearly and try again.", added=False), 422
    except (TypeError, ValueError):
        return jsonify(error="Invalid recognition confidence."), 400
    with LOCK:
        existing = next((item for item in ITEMS.values() if item["name"].casefold() == product["name"].casefold()), None)
        if existing:
            existing["qty"] = min(99, existing["qty"] + 1)
        else:
            iid = max(ITEMS.keys(), default=0) + 1
            ITEMS[iid] = dict(id=iid, **product, qty=1)
        sync_list_from_cart()
    return jsonify(state())


@app.route("/api/ocr/status")
def api_ocr_status():
    return jsonify(ocr_status())


@app.route("/api/list/scan", methods=["POST"])
def api_list_scan():
    uploaded = request.files.get("image")
    if not uploaded or not uploaded.filename:
        return jsonify(error="Capture a clear image of your grocery list using the cart camera."), 400
    diagnostics = ocr_status()
    if not diagnostics.get("ready"):
        return jsonify(error=diagnostics["message"], diagnostics=diagnostics), 503
    try:
        image = Image.open(io.BytesIO(uploaded.read())).convert("RGB")
        image.thumbnail((2400, 2400))
        raw = pytesseract.image_to_string(image, config="--psm 6")
    except Exception as exc:
        return jsonify(error="Tesseract is installed but the scan failed. Check the photo and OCR diagnostics, then retry.", detail=str(exc), diagnostics=ocr_status()), 503
    candidates = []
    seen = set()
    for line in raw.splitlines():
        line = re.sub(r"^\s*(?:[-*•☐☑✓✔▪]+\s*|\d+[.)]\s*)", "", line).strip(" 	-•;,:|")
        line = re.sub(r"\s+", " ", line)
        if not line or len(line) < 2 or len(line) > 80:
            continue
        if line.lower().strip(" :") in {"shopping list", "grocery list", "my list", "items", "groceries", "shopping"}:
            continue
        # Split simple comma-separated lines while preserving ordinary item names.
        parts = [p.strip(" 	-•;:") for p in line.split(",")] if "," in line else [line]
        for item in parts:
            key = item.casefold()
            if len(item) >= 2 and key not in seen:
                seen.add(key); candidates.append(item)
    if not candidates:
        return jsonify(error="No grocery items were recognised. Try a clearer, well-lit photo with one item per line.", raw_text=raw), 422
    return jsonify(candidates=candidates, raw_text=raw)


@app.route("/api/list/confirm", methods=["POST"])
def api_list_confirm():
    global SHOPPING_LIST, NEXT_LIST_ID
    data = request.get_json(force=True) or {}
    names = data.get("items", [])
    if not isinstance(names, list):
        return jsonify(error="Items must be a list."), 400
    cleaned, seen = [], set()
    for value in names:
        name = re.sub(r"\s+", " ", str(value or "")).strip()[:80]
        if name and name.casefold() not in seen:
            cleaned.append(name); seen.add(name.casefold())
    with LOCK:
        SHOPPING_LIST = []
        for name in cleaned:
            SHOPPING_LIST.append(dict(id=NEXT_LIST_ID, name=name, done=False)); NEXT_LIST_ID += 1
        sync_list_from_cart()
    return jsonify(state())


@app.route("/api/list/add", methods=["POST"])
def api_list_add():
    global NEXT_LIST_ID
    data = request.get_json(force=True) or {}
    name = re.sub(r"\s+", " ", str(data.get("name", ""))).strip()[:80]
    if not name:
        return jsonify(error="Enter an item name."), 400
    with LOCK:
        if not any(x["name"].casefold() == name.casefold() for x in SHOPPING_LIST):
            SHOPPING_LIST.append(dict(id=NEXT_LIST_ID, name=name, done=False)); NEXT_LIST_ID += 1
        sync_list_from_cart()
    return jsonify(state())


@app.route("/api/list/toggle/<int:item_id>", methods=["POST"])
def api_list_toggle(item_id):
    with LOCK:
        for item in SHOPPING_LIST:
            if item["id"] == item_id:
                item["done"] = not item["done"]
                break
    return jsonify(state())


@app.route("/api/list/delete/<int:item_id>", methods=["POST"])
def api_list_delete(item_id):
    global SHOPPING_LIST
    with LOCK:
        SHOPPING_LIST = [x for x in SHOPPING_LIST if x["id"] != item_id]
    return jsonify(state())


@app.route("/api/session/start", methods=["POST"])
def api_session_start():
    global SESSION_ACTIVE
    with LOCK:
        SESSION_ACTIVE = True
    return jsonify(state())


@app.route("/api/session/end", methods=["POST"])
def api_session_end():
    global SESSION_ACTIVE, SHOPPING_LIST
    with LOCK:
        SESSION_ACTIVE = False
        SHOPPING_LIST = []
        ITEMS.clear()
        S["anomaly"] = False
    return jsonify(state())


@app.route("/api/cart/reset", methods=["POST"])
def api_reset():
    with LOCK:
        ITEMS.clear(); S["anomaly"] = False
        sync_list_from_cart()
    return jsonify(state())


@app.route("/api/settings", methods=["POST"])
def api_settings():
    d = request.get_json(force=True) or {}
    with LOCK:
        for k in ("dark", "talkback", "contrast"):
            if k in d: S[k] = bool(d[k])
        if d.get("font") in (100, 125, 150): S["font"] = d["font"]
    return jsonify(state())


@app.route("/api/anomaly", methods=["POST"])
def api_anomaly():
    d = request.get_json(force=True) or {}
    with LOCK: S["anomaly"] = bool(d.get("on", True))
    return jsonify(state())


def frames():
    cap = None
    if cv2:
        try:
            cap = cv2.VideoCapture(0)
            if not cap.isOpened(): cap = None
        except Exception:
            cap = None
    t = 0
    while cv2:
        ok, fr = (cap.read() if cap else (False, None))
        if not ok:  # photo-based demo shelf when a physical camera is unavailable
            fr = np.full((480, 640, 3), (245, 241, 232), np.uint8)  # warm cream, BGR
            cv2.rectangle(fr, (0, 150), (640, 158), (225, 221, 211), -1)
            cv2.rectangle(fr, (0, 332), (640, 340), (225, 221, 211), -1)
            cv2.putText(fr, "SMARTCART  /  PRODUCT RECOGNITION DEMO", (24, 38), cv2.FONT_HERSHEY_SIMPLEX, .58, (37, 41, 37), 1, cv2.LINE_AA)
            photos = [("milk.jpg", (112, 52, 110, 92)), ("bananas.jpg", (300, 50, 110, 92)), ("produce.jpg", (474, 50, 110, 92))]
            for filename, (x, y, tw, th) in photos:
                path = os.path.join(app.static_folder, "products", filename)
                photo = cv2.imread(path) if os.path.exists(path) else None
                cv2.rectangle(fr, (x - 8, y - 8), (x + tw + 8, y + th + 8), (255, 255, 255), -1)
                if photo is not None:
                    ph, pw = photo.shape[:2]; scale = min(tw / max(1, pw), th / max(1, ph))
                    photo = cv2.resize(photo, (max(1, int(pw * scale)), max(1, int(ph * scale))))
                    yy, xx = y + (th - photo.shape[0]) // 2, x + (tw - photo.shape[1]) // 2
                    fr[yy:yy + photo.shape[0], xx:xx + photo.shape[1]] = photo
            cv2.putText(fr, "Products are shown using real image assets", (24, 452), cv2.FONT_HERSHEY_SIMPLEX, .5, (92, 112, 102), 1, cv2.LINE_AA)
        h, w = fr.shape[:2]
        green, j = (70, 125, 46), int(2 * np.sin(t / 6))
        for (a, b, lab) in [((int(w * .15) + j, int(h * .12)), (int(w * .39) + j, int(h * .73)), "Milk  ·  Recognised"),
                            ((int(w * .47), int(h * .12) - j), (int(w * .72), int(h * .73) - j), "Bananas  ·  Recognised")]:
            cv2.rectangle(fr, a, b, green, 2)
            label_w = min(w - a[0], max(150, int(len(lab) * 8.5)))
            cv2.rectangle(fr, (a[0], max(0, a[1] - 24)), (a[0] + label_w, a[1]), green, -1)
            cv2.putText(fr, lab, (a[0] + 7, a[1] - 7), cv2.FONT_HERSHEY_SIMPLEX, .43, (255, 255, 255), 1, cv2.LINE_AA)
        ok, buf = cv2.imencode(".jpg", fr, [cv2.IMWRITE_JPEG_QUALITY, 70])
        if ok: yield b"--frame\r\nContent-Type: image/jpeg\r\n\r\n" + buf.tobytes() + b"\r\n"
        t += 1; time.sleep(0.06)


@app.route("/video_feed")
def video_feed():
    if not cv2: return Response("OpenCV not installed", status=503)
    return Response(frames(), mimetype="multipart/x-mixed-replace; boundary=frame")


