{id:'bakery',n:'Bakery',c:'Bakery',s:'Aisle 04 Front',x:200,y:32,ex:270,ey:162},
{id:'drinks',n:'Beverages',c:'Beverages',s:'Aisles 06-07',x:370,y:32,ex:440,ey:162},
{id:'dairy',n:'Dairy',c:'Dairy',s:'Refrigerated Bay B',x:30,y:196,ex:100,ey:338},
{id:'frozen',n:'Frozen',c:'Frozen',s:'Aisles 09-10',x:200,y:196,ex:270,ey:338},
{id:'snacks',n:'Snacks &amp; Chocolates',c:'Chocolates',s:'Aisle 08 East',x:370,y:196,ex:440,ey:338},
{id:'meat',n:'Meat &amp; Seafood',c:'Meat',s:'Back Counter',x:30,y:384,ex:100,ey:510},
